; 60K BDOS  -- CP/M 2.2 BDOS adapted to the Apple II Language Card (LC)
; ===========================================================================
; This is the standard CP/M 2.2 BDOS (serial BD16000 / 14D40, identical to the
; 44K sysimg_223 BDOS) but RELOCATED and BANK-WOVEN for the 60K LC system.
;
; STRUCTURE (standard CP/M 2.2 BDOS layout, all present):
;   $DC00  BD 16 00 01 4D 40   serial number (== 44K BDOS, unchanged)
;   $DC06  C3 11 DC            JP BDOS_ENTRY   = BDOS primary entry (== 44K JP $9C11)
;   $DC09  jump/vector quad ($DCA5,$DCB2,$DCB7,$DCBC)
;   $DC11  dispatch preamble (see DELTA below)
;   $DC53  41-entry function-pointer table (BDOS funcs 0..40 / $00..$28)
;   ...    FCB / file primitives, directory, disk I/O, console redirection.
;
; LANGUAGE-CARD WINDOW MAP (running system):
;   Z-80 $Bxxx..$DFFF  -> Apple $Dxxx..$FFFF  (the 16K Language Card)
;     so Z-80 $DCxx -> Apple $FCxx (UPPER LC),  Z-80 $Bxxx -> Apple $Dxxx (LOWER LC)
;   Z-80 $E08B/$E083   -> Apple $C08B/$C083    (LC soft-switches in the I/O window)
;     $C08B = read-RAM / write-RAM, bank1     $C083 = read-RAM / write-RAM, bank2
;
; THE SPLIT (dispatch table at $DC53, 41 entries):
;   - 11 funcs live in the UPPER LC at $DCxx-$DFxx  (Apple $FCxx-$FFxx) -- the
;     same window the dispatcher itself occupies; these are the BIOS-adjacent
;     console/line-edit/search helpers.
;   -  3 entries are delegated straight to the BIOS at $FA03/$FA0F/$FA12
;     (WBOOT + 2 console BIOS calls).
;   - 27 funcs live in the LOWER LC at $Bxxx (Apple $Dxxx) -- the bulk of the
;     FCB/file/directory/disk machinery was relocated DOWN into the lower bank.
;   BDOS scratch/zero-page-equivalent variables sit at $BFxx (Apple $DFxx);
;     referenced ~130 times across the body.
;
; LANGUAGE-CARD BANK-SWITCH ACCESSES (13 total, all WRITES; no ROM-read modes):
;   $DC11  LD ($E08B),A   entry: bank-in LC (Apple $C08B)
;   $DC3F  LD ($E083),A   funcs <12: select bank2 (Apple $C083)
;   $DD5B  LD ($E08B),A   $DD64  LD ($E083),A   (helper bank flip)
;   $DF1C/$DF20/$DF28     LD ($E083),A   (lower-LC trampoline glue)
;   $DF36  LD ($E08B),A   $DF3C  LD ($E083),A
;   $DF41/$DF45  LD ($E08B),A           (epilogue: bank-out / restore on exit)
;   $DF63  LD ($E083),A   $DF81  LD ($E083),A
;   => 5x $E08B (Apple $C08B), 8x $E083 (Apple $C083).
;
; DISPATCH-PREAMBLE DELTA vs 44K BDOS (sysimg_223 off 0xD00, entry $9C11):
;   44K $9C11:  EB            EX DE,HL
;               22 43 9F      LD ($9F43),HL    ; save DE param, NO banking
;               ... 32 E0 A9 / 32 DE A9        ; plain RAM scratch ($A9xx)
;   60K $DC11:  32 8B E0      LD ($E08B),A     ; <-- inserted LC BANK-IN first
;               ED 53 11 DF   LD (BDOS_PARAM_PTR),DE    ; save DE param (LC scratch)
;               32 E3 BF      LD (DRV_SELECT_ARG),A     ; mirror to lower-LC scratch
;               ... 31 0F DF  LD SP,BDOS_STACK_TOP      ; private stack in LC
;               21 45 DF / E5 PUSH $DF45       ; return -> bank-OUT epilogue
;               FE 0C / 32 83 E0  (func<12) LD ($E083),A  ; bank2 select
;   Both keep the SAME func-count guard (CP $29 = 41 functions) and the same
;   table-indexed JP (HL).  The 60K version simply wraps every call in a
;   bank-in (entry) / bank-out ($DF45 epilogue) envelope and scatters the body
;   across the two LC banks; the 44K version runs entirely in flat RAM.
; ===========================================================================

    IFNDEF CPM60_LINK  ; [link] master defines CPM60_LINK and owns this; standalone keeps it
    DEVICE NOSLOT64K
    ENDIF

; -- External symbols --
WBOOTV            EQU $0000               ; Warm-boot vector — JP WBOOT in BIOS. Touching it causes a CP/M warm boot.
IOBYTE_ADDR               EQU $0003               ; [DOC S&HD 2-18..2-21] I/O assignment byte at $0003: maps four logical
                                             ; devices to physical devices via four 2-bit fields -- CONSOLE (bits 0-1),
                                             ; READER (bits 2-3), PUNCH (bits 4-5), LIST (bits 6-7). Read/written by BDOS
                                             ; funcs 7 (Get I/O Byte) and 8 (Set I/O Byte); selects which I/O Vector Table
                                             ; entry (#1 vs #2) the BIOS console/reader/punch/list routines use.
WBOOT                EQU $FA03               ; BIOS entry 1  -- warm boot (on SoftCard 2.23: jumps to $FAB8)
CONST                EQU $FA06               ; BIOS entry 2  -- console status
CONIN                EQU $FA09               ; BIOS entry 3  -- console input
CONOUT               EQU $FA0C               ; BIOS entry 4  -- console output
LIST                 EQU $FA0F               ; BIOS entry 5  -- printer (LIST device) output
PUNCH                EQU $FA12               ; BIOS entry 6  -- punch device output
READER               EQU $FA15               ; BIOS entry 7  -- reader device input
HOME                 EQU $FA18               ; BIOS entry 8  -- seek drive to track 0
SELDSK               EQU $FA1B               ; BIOS entry 9  -- select drive, returns its DPH
SETTRK               EQU $FA1E               ; BIOS entry 10 -- set track for the next access
SETSEC               EQU $FA21               ; BIOS entry 11 -- set sector for the next access
SETDMA               EQU $FA24               ; BIOS entry 12 -- set the DMA (transfer) address
READ                 EQU $FA27               ; BIOS entry 13 -- read one 128-byte record
WRITE                EQU $FA2A               ; BIOS entry 14 -- write one 128-byte record
SECTRAN              EQU $FA30               ; BIOS entry 16 -- logical-to-physical sector translate
; -- Language-Card bank-select soft switches (Z-80 $E08x -> Apple $C08x I/O window) --
LC_BANK1             EQU $E08B               ; select LC read/write RAM, bank 1 (Apple $C08B)
LC_BANK2             EQU $E083               ; select LC read/write RAM, bank 2 (Apple $C083)

    IFNDEF CPM60_LINK  ; [link] master defines CPM60_LINK and owns this; standalone keeps it
    ORG $DC00
    ELSE
    DISP $DC00         ; linked: upper-bank labels at run $DC00, emit at the master's file pos
    ENDIF

