DIR_SEARCH_FIRST:
        LD A,$FF                         ; $B980  3E FF
        LD (DIR_MATCH_FLAG),A                     ; $B982  32 E1 BF
        LD HL,DIR_CMP_LEN                      ; $B985  21 E5 BF
        LD (HL),C                        ; $B988  71
