        CALL CUR_RECORD_BYTES_EQUAL                    ; $B99A  CD 6B B8
        JR Z,DIR_NO_MATCH                  ; $B99D  28 52
        LD HL,(DIR_FCB_PTR)                    ; $B99F  2A E6 BF
        EX DE,HL                         ; $B9A2  EB
