        ADD HL,DE                        ; $BACA  19
        LD C,(HL)                        ; $BACB  4E
        LD HL,$000F                      ; $BACC  21 0F 00
        ADD HL,DE                        ; $BACF  19
        LD B,(HL)                        ; $BAD0  46
        POP HL                           ; $BAD1  E1
        POP AF                           ; $BAD2  F1
        LD (HL),A                        ; $BAD3  77
        LD A,C                           ; $BAD4  79
        CP (HL)                          ; $BAD5  BE
        LD A,B                           ; $BAD6  78
        JR Z,FILE_SIZE_STORE                  ; $BAD7  28 06
        LD A,$00                         ; $BAD9  3E 00
        JR C,FILE_SIZE_STORE                  ; $BADB  38 02
